#!/usr/bin/env bash
set -euo pipefail
cd "${1:-$PWD}"

[[ -f tools/run-cdvd-frontier.sh && -f src/ps2/cdvd_rpc_historical_recovered.c ]] || {
  echo "Apply Progress 43 first and run from the repository root." >&2
  exit 2
}

python3 - <<'PY'
from pathlib import Path
Path("tools/run-cdvd-frontier.sh").write_text('#!/usr/bin/env bash\nset -euo pipefail\n\nROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"\ncd "$ROOT"\n\nDEFAULT_EE_CC="$ROOT/build/toolchains/ee-gcc-3.2.2-stage1/prefix/bin/ee-gcc"\nEE_CC="${EE_CC:-$DEFAULT_EE_CC}"\nEE_OBJDUMP="$(dirname "$EE_CC")/ee-objdump"\n\nif [[ ! -x "$EE_CC" ]]; then\n    echo "Missing historical EE compiler: $EE_CC" >&2\n    exit 2\nfi\n\nBUILD="$ROOT/build/matching/cdvd_rpc"\nmkdir -p "$BUILD"\n\nRAW="$BUILD/listing.bin"\nSOURCE="$ROOT/src/ps2/cdvd_rpc_historical_recovered.c"\nMANIFEST="$ROOT/analysis/matching/cdvd_rpc_listing.csv"\n\nrm -f "$BUILD"/profile-*.o\nrm -f "$BUILD"/profile-*.report.md\nrm -f "$BUILD"/profile-*.summary.txt\nrm -f "$BUILD"/profile-*.compile.log\nrm -f "$BUILD"/profile-scores.tsv\nrm -f "$BUILD"/best-profile.txt\nrm -f "$BUILD"/best-objdump.txt\nrm -f "$RAW"\n\npython3 tools/objdump_listing_to_binary.py \\\n  --input analysis/functions/cdvd_rpc_0019be70.asm \\\n  --output "$RAW" \\\n  --base-address 0x0019be70 \\\n  --end-address 0x0019c364 >/dev/null\n\nCOMMON=(\n  -G0 -EL -Wall -fshort-double -mlong64\n  -mhard-float -mno-abicalls -march=r5900 -mtune=r5900\n  -DPS2_EE -D_EE -DLSB_FIRST -DALIGN_DWORD -DCODE_PLATFORM=3\n)\n\ncompile_profile() {\n    local name="$1"\n    shift\n    local obj="$BUILD/profile-${name}.o"\n    local report="$BUILD/profile-${name}.report.md"\n    local summary="$BUILD/profile-${name}.summary.txt"\n    local clog="$BUILD/profile-${name}.compile.log"\n\n    if ! "$EE_CC" "$@" "${COMMON[@]}" -c "$SOURCE" -o "$obj" >"$clog" 2>&1; then\n        printf \'%s\\tCOMPILE_FAIL\\t0\\t0\\t999999\\n\' "$name" >>"$BUILD/profile-scores.tsv"\n        return 0\n    fi\n\n    python3 tools/compare_elf_functions.py \\\n      --target "$RAW" \\\n      --base-address 0x0019be70 \\\n      --object "$obj" \\\n      --manifest "$MANIFEST" \\\n      --report "$report" >/dev/null\n\n    python3 tools/summarize_matching_report.py "$report" >"$summary"\n\n    python3 - "$name" "$summary" >>"$BUILD/profile-scores.tsv" <<\'PY\'\nimport re\nimport sys\nfrom pathlib import Path\n\nname = sys.argv[1]\ntext = Path(sys.argv[2]).read_text(encoding="utf-8")\n\nm = re.search(r"matching summary:\\s*(\\d+)/(\\d+)", text)\nif not m:\n    print(f"{name}\\tPARSE_FAIL\\t0\\t0\\t999999")\n    raise SystemExit\n\nmatches = int(m.group(1))\ntotal = int(m.group(2))\nequal_sizes = matches\nsize_delta = 0\n\nfor line in text.splitlines():\n    mm = re.search(r"MISS\\s+.*?:\\s*(\\d+)\\s*/\\s*(\\d+)", line)\n    if not mm:\n        continue\n    target = int(mm.group(1))\n    obj = int(mm.group(2))\n    if target == obj:\n        equal_sizes += 1\n    size_delta += abs(target - obj)\n\nprint(f"{name}\\tOK\\t{matches}\\t{equal_sizes}\\t{size_delta}")\nPY\n}\n\n# 1) Exact SNESticle 3.2.2-b1 source-build style.\ncompile_profile snesticle-o2 \\\n  -O2 -pipe -Wa,-al \\\n  -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -ffreestanding -fno-builtin\n\n# 2) Same O2 contract but permit builtins.  This is the Progress-43 baseline\n#    that produced the target-sized 0x160-byte CDVD_FindFile.\ncompile_profile station-o2-builtins \\\n  -O2 -pipe -Wa,-al \\\n  -fomit-frame-pointer -fstrict-aliasing -fno-common\n\n# 3) PGEN\'s historical optimization level with a minimal flag surface.\ncompile_profile pgen-o3-minimal \\\n  -O3\n\n# 4) PGEN O3 plus the explicit R5900-era codegen hygiene already established\n#    elsewhere in this decompilation.\ncompile_profile pgen-o3-omit \\\n  -O3 -pipe -Wa,-al \\\n  -fomit-frame-pointer -fstrict-aliasing -fno-common\n\n# 5) Test whether the PGEN O3 source family was still compiled freestanding.\ncompile_profile pgen-o3-freestanding \\\n  -O3 -pipe -Wa,-al \\\n  -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -ffreestanding -fno-builtin\n\n# 6) Scheduling fingerprint probes.  These are diagnostic only.\ncompile_profile o2-builtins-nosched2 \\\n  -O2 -pipe -Wa,-al \\\n  -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-schedule-insns2\n\ncompile_profile o3-builtins-nosched2 \\\n  -O3 -pipe -Wa,-al \\\n  -fomit-frame-pointer -fstrict-aliasing -fno-common \\\n  -fno-schedule-insns2\n\nBEST="$(python3 - "$BUILD/profile-scores.tsv" <<\'PY\'\nimport sys\nfrom pathlib import Path\n\nrows = []\nfor line in Path(sys.argv[1]).read_text(encoding="utf-8").splitlines():\n    parts = line.split("\\t")\n    if len(parts) != 5 or parts[1] != "OK":\n        continue\n    name = parts[0]\n    matches = int(parts[2])\n    equal_sizes = int(parts[3])\n    delta = int(parts[4])\n    rows.append((matches, equal_sizes, -delta, name))\n\nif not rows:\n    raise SystemExit("no CDVD profile compiled successfully")\n\nrows.sort(reverse=True)\nprint(rows[0][3])\nPY\n)"\n\nprintf \'%s\\n\' "$BEST" >"$BUILD/best-profile.txt"\n\necho "=== CDVD historical profile matrix ==="\nprintf \'%-26s %7s %11s %10s\\n\' "profile" "matches" "same-size" "size-delta"\nwhile IFS=$\'\\t\' read -r name status matches equal_sizes delta; do\n    if [[ "$status" == "OK" ]]; then\n        marker=" "\n        [[ "$name" == "$BEST" ]] && marker="*"\n        printf \'%s %-24s %7s/8 %11s/8 %10s\\n\' \\\n          "$marker" "$name" "$matches" "$equal_sizes" "$delta"\n    else\n        printf \'  %-24s %s\\n\' "$name" "$status"\n    fi\ndone <"$BUILD/profile-scores.tsv"\n\necho\necho "=== best profile: $BEST ==="\ncat "$BUILD/profile-${BEST}.summary.txt"\n\nif [[ -x "$EE_OBJDUMP" ]]; then\n    "$EE_OBJDUMP" -dr "$BUILD/profile-${BEST}.o" >"$BUILD/best-objdump.txt" 2>/dev/null || true\nfi\n\nif grep -q \'matching summary: 8/8\' "$BUILD/profile-${BEST}.summary.txt"; then\n    echo\n    echo "=== strict gate ==="\n    python3 tools/compare_elf_functions.py \\\n      --target "$RAW" \\\n      --base-address 0x0019be70 \\\n      --object "$BUILD/profile-${BEST}.o" \\\n      --manifest "$MANIFEST" \\\n      --report "$BUILD/profile-${BEST}.report.md" \\\n      --require-all-matching\n    echo "CDVD RPC strict listing gate: OK"\nfi\n\necho\necho "Best profile saved to: build/matching/cdvd_rpc/best-profile.txt"\necho "Best disassembly:       build/matching/cdvd_rpc/best-objdump.txt"\n', encoding="utf-8")
Path("tools/test_progress44_cdvd_profile_matrix.py").write_text('from pathlib import Path\nimport unittest\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass Progress44CdvdProfileMatrixTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.runner = (ROOT / "tools/run-cdvd-frontier.sh").read_text(\n            encoding="utf-8"\n        )\n\n    def test_tests_historical_snesticle_profile(self):\n        self.assertIn("compile_profile snesticle-o2", self.runner)\n        self.assertIn("-ffreestanding -fno-builtin", self.runner)\n\n    def test_tests_pgen_o3_profile(self):\n        self.assertIn("compile_profile pgen-o3-minimal", self.runner)\n        self.assertIn("compile_profile pgen-o3-omit", self.runner)\n\n    def test_tests_scheduler_fingerprint(self):\n        self.assertIn("o2-builtins-nosched2", self.runner)\n        self.assertIn("-fno-schedule-insns2", self.runner)\n\n    def test_selects_best_profile_without_reusing_objects(self):\n        self.assertIn(\'rm -f "$BUILD"/profile-*.o\', self.runner)\n        self.assertIn("profile-scores.tsv", self.runner)\n        self.assertIn("best-profile.txt", self.runner)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', encoding="utf-8")
Path("docs/PROGRESS44.md").write_text('# Progress 44 — CDVD historical compiler-profile matrix\n\nProgress 43 established that the recovered source family is extremely close to\nthe SNES Station CDVD corridor, but the first probe was 0/8.\n\nThat 0/8 is not a structural rejection:\n\n- five functions already have exactly the target size;\n- `CDVD_Init` and `CDVD_FindFile` are target-sized;\n- the differences largely begin in prologue scheduling or register choice;\n- the target contains `CDVD_GetSize`, which survives in the PGEN revision of\n  the same old libcdvd family.\n\nTwo historical build profiles are now known:\n\n- SNESticle: GCC 3.2.2-b1, `-O2`, freestanding, no builtins, explicit R5900.\n- PGEN: `-O3 -G0 -Wall -fshort-double -mlong64`.\n\nThe runner therefore compiles the same historical source under a small,\nevidence-driven profile matrix and ranks profiles by:\n\n1. exact function matches;\n2. number of functions with target-identical size;\n3. total function-size delta.\n\nIt also includes `-fno-schedule-insns2` diagnostic variants because several\nremaining differences are instruction-order fingerprints.\n\nThis step does not promote any profile to historical truth by itself.  It is a\ncompiler-fingerprint experiment.  The winning profile must still pass the\nbyte comparator and strict gate.\n', encoding="utf-8")
PY

chmod +x tools/run-cdvd-frontier.sh

echo "Progress 44 applied."
echo "Run only:"
echo "  ./tools/run-cdvd-frontier.sh"
